const express = require('express');
const app = express();

// Middleware to parse JSON requests
app.use(express.json());

// Helper function to evaluate a rule expression against the request context
function evalRule(req) {
  const expr = req.body.rule; // e.g. 'ctx.amount > 100'
  const ctx = { ctx: req.body.context, req };
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req); // dynamic eval
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// POST /check endpoint to evaluate a rule expression
app.post('/check', (req, res) => {
  if (!req.body.rule || !req.body.context) {
    return res.status(400).json({ error: 'Missing rule or context in request body' });
  }

  try {
    const result = evalRule(req);
    res.json({ result });
  } catch (err) {
    res.status(400).json({ error: 'Invalid rule expression', details: err.message });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

